export const API_VERSION = "v1";

export function createCustomerClient(options: ClientOptions) {
  return createClient<Operations>(operations, options);
}

export type CustomerClient = ReturnType<typeof createCustomerClient>;
export type Input<N extends keyof Operations> = Operations[N]["input"];
export type Output<N extends keyof Operations> = Operations[N]["output"];
